This is a greedy list-scheduling solution with a simulated timeline.

**Approach**

1. Parse the input and process the files in input order, which is a topological order.
2. Select targets: for each target, compute its needed ancestor set. Process targets by increasing deadline, which favors earlier ones. Compute a lower bound on each target's finish time as the critical path (the longest chain of compile times). Drop a target if that bound exceeds its deadline.
3. Simulate the schedule. Keep `avail[f][s]`, the time file f is available on server s. Each server has a free time. Schedule events in submission order. Since each server executes its steps in submission order, an event simulation that appends steps one at a time is valid.
4. For each selected target in order of deadline, and each of its needed files in topological order that is not yet compiled anywhere, choose the server that gives the earliest finish time. The start time is max(server free time, max over dependencies of their availability on that server). The availability of a dependency on a server is min(finish on that server, earliest finish elsewhere plus replication time).
5. Store per file the best "global" finish time `fin[f]` (the earliest compile finish plus replication time, for other servers) and the per-server finish. To keep memory low, store per file a small list of (server, finish) pairs, since most files are compiled once. Availability on server s is min over the pairs of (finish if same server, else finish + r).
6. Compile the target's missing dependencies in topological order, each on the earliest-finish server. Afterward, check whether the target meets its deadline. If it does not, the steps are already committed, which wastes time, so the check is done beforehand by a trial: compute the plan with temporary state, and commit only if the target finishes by its deadline. To keep this simple, evaluate the plan by simulating with a copy of the touched state, then roll back if it fails.

Rollback is implemented with an undo log: record the previous server free times and the added pair entries, then revert them.

Cost: the missing ancestors per target could be large. Each file is compiled at most once, except when a trial fails, so the trial cost is bounded by the traversal of the uncompiled ancestors. A failed trial is repeated work, so limit this by pre-filtering with the critical path bound. Per file, the server choice costs S times the number of dependencies (at most 100), which is about 100·100·1e5 = 1e9 in the worst case. To keep it lighter, compute each dependency's availability per server by looking at its pair list, which is usually of length 1. I accept this.

The output is the committed steps in order.

```cpp
#include <bits/stdc++.h>
using namespace std;
int C,T,S;
vector<long long> ct,rt;
vector<vector<int>> dep;
vector<vector<pair<int,long long>>> pr;
vector<long long> fr;
long long avl(int f,int s){
    long long b=LLONG_MAX;
    for(auto&p:pr[f]){
        long long v=p.first==s?p.second:p.second+rt[f];
        b=min(b,v);
    }
    return b;
}
int main(){
    scanf("%d %d %d",&C,&T,&S);
    unordered_map<string,int> id;
    ct.resize(C);rt.resize(C);dep.resize(C);
    char buf[64];
    for(int i=0;i<C;i++){
        long long c,r;
        scanf("%s %lld %lld",buf,&c,&r);
        id[buf]=i;ct[i]=c;rt[i]=r;
        int n;scanf("%d",&n);
        for(int j=0;j<n;j++){scanf("%s",buf);dep[i].push_back(id[buf]);}
    }
    vector<array<long long,3>> tg(T);
    for(int i=0;i<T;i++){
        long long d,g;
        scanf("%s %lld %lld",buf,&d,&g);
        tg[i]={d,g,id[buf]};
    }
    vector<long long> cp(C);
    for(int i=0;i<C;i++){
        long long m=0;
        for(int d:dep[i])m=max(m,cp[d]);
        cp[i]=m+ct[i];
    }
    sort(tg.begin(),tg.end());
    pr.assign(C,{});
    fr.assign(S,0);
    vector<pair<int,int>> out;
    vector<int> mark(C,0);
    int stamp=0;
    for(auto&t:tg){
        int f=t[2];
        if(cp[f]>t[0])continue;
        stamp++;
        vector<int> need,stk={f};
        mark[f]=stamp;
        while(!stk.empty()){
            int x=stk.back();stk.pop_back();
            if(!pr[x].empty())continue;
            need.push_back(x);
            for(int d:dep[x])if(mark[d]!=stamp){mark[d]=stamp;stk.push_back(d);}
        }
        sort(need.begin(),need.end());
        vector<long long> savedFr=fr;
        vector<pair<int,int>> added;
        bool ok=true;
        long long fin=0;
        for(int x:need){
            long long best=LLONG_MAX;int bs=0;
            for(int s=0;s<S;s++){
                long long st=fr[s];
                for(int d:dep[x])st=max(st,avl(d,s));
                long long e=st+ct[x];
                if(e<best){best=e;bs=s;}
            }
            pr[x].push_back({bs,best});
            fr[bs]=best;
            added.push_back({x,bs});
            if(x==f)fin=best;
            if(best>t[0]){ok=false;break;}
        }
        if(ok){
            for(auto&a:added)out.push_back(a);
        }else{
            for(auto&a:added)pr[a.first].clear();
            fr=savedFr;
        }
    }
    vector<string> nm(C);
    for(auto&k:id)nm[k.second]=k.first;
    if(out.empty()){
        // must output at least one step
        int f=tg[0][2];
        vector<int> need;
        vector<char> seen(C,0);
        vector<int> stk={f};seen[f]=1;
        while(!stk.empty()){
            int x=stk.back();stk.pop_back();need.push_back(x);
            for(int d:dep[x])if(!seen[d]){seen[d]=1;stk.push_back(d);}
        }
        sort(need.begin(),need.end());
        printf("%d\n",(int)need.size());
        for(int x:need)printf("%s 0\n",nm[x].c_str());
        return 0;
    }
    printf("%d\n",(int)out.size());
    for(auto&a:out)printf("%s %d\n",nm[a.first].c_str(),a.second);
}
